return ['domain'=>'publishpress-hub% 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar% 100 >= 3 && n % 100 <= 10 ? 3: n % 100 >= 11 ? 4 : 5);&& n%100<=10 ? 3: n%100>=11 ? 4 : 5);','project-id-version'=>'PublishPress Hub 1.0.4-beta.3','pot-creation-date'=>'2026-06-02T15:44:37+00:00','po-revision-date'=>'2026-09-03 09:38+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['PublishPress Hub'=>'نشاط PublishPress','Centralized management hub for all PublishPress plugins - install, update, and manage licenses from one dashboard.'=>'مركز إدارة مركزي لجميع إضافات PublishPress - قم بتثبيت وتحديث وإدارة التراخيص من لوحة تحكم واحدة.','PublishPress'=>'PublishPress','https://publishpress.com'=>'https://publishpress.com','Please wait while we load the components showcase...'=>'يرجى الانتظار بينما نقوم بتحميل عرض المكونات...','Please wait while we load the plugins dashboard...'=>'يرجى الانتظار بينما نقوم بتحميل لوحة تحكم الإضافات...','Settings'=>'الإعدادات','Please wait while we load the settings page...'=>'يرجى الانتظار بينما نقوم بتحميل صفحة الإعدادات...','You do not have sufficient permissions to access this page.'=>'ليس لديك صلاحيات كافية للوصول إلى هذه الصفحة.','Welcome'=>'مرحبًا','Please wait while we load the welcome page...'=>'يرجى الانتظار بينما نقوم بتحميل صفحة الترحيب...','Warning: The license for %1$s has expired. %2$s'=>'تحذير: انتهت صلاحية الترخيص لـ %1$s. %2$s','Manage licenses'=>'إدارة التراخيص','Warning: %1$d plugin(s) have expired licenses: %2$s. %3$s'=>'تحذير: %1$d إضافة(ات) انتهت صلاحية تراخيصها: %2$s. %3$s','Object must be loaded before initializing.'=>'يجب تحميل الكائن قبل التهيئة.','No license key found'=>'لم يتم العثور على مفتاح الترخيص','Free plugin not set for plugin family: %s'=>'لم يتم تعيين إضافة مجانية لعائلة الإضافات: %s','Pro plugin not set for plugin family: %s'=>'لم يتم تعيين إضافة مدفوعة لعائلة الإضافات: %s','License activation error. Please try again later or contact support for help.'=>'خطأ في تفعيل الترخيص. يرجى المحاولة لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','License deactivation error. Please try again later or contact support for help.'=>'خطأ في إلغاء تفعيل الترخيص. يرجى المحاولة لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','This license is currently disabled. Please contact support for help.'=>'هذه الرخصة معطلة حالياً. يرجى الاتصال بالدعم للحصول على المساعدة.','This license has expired. Please contact support to renew it.'=>'انتهت صلاحية هذه الرخصة. يرجى الاتصال بالدعم لتجديدها.','This license key is not authorized for this plugin. Please verify your license key or contact support for help.'=>'مفتاح الترخيص هذا غير مصرح به لهذه الإضافة. يرجى التحقق من مفتاح الترخيص الخاص بك أو الاتصال بالدعم للحصول على المساعدة.','This license cannot be used for this plugin. Please contact support for help.'=>'لا يمكن استخدام هذا الترخيص لهذه الإضافة. يرجى الاتصال بالدعم للحصول على المساعدة.','This license does not match the plugin you are trying to activate. Please contact support for assistance.'=>'هذا الترخيص لا يتطابق مع الإضافة التي تحاول تفعيلها. يرجى الاتصال بالدعم للحصول على المساعدة.','License key does not match our records. Please contact support for assistance.'=>'مفتاح الترخيص لا يتطابق مع سجلاتنا. يرجى الاتصال بالدعم للحصول على المساعدة.','No license key provided. Please enter a valid license key.'=>'لم يتم تقديم مفتاح رخصة. يرجى إدخال مفتاح رخصة صالح.','Your site URL is required to activate the license. Please enter a valid site URL to continue.'=>'عنوان URL لموقعك مطلوب لتفعيل الترخيص. يرجى إدخال عنوان URL صالح للموقع للمتابعة.','License activation limit reached. Please contact support to upgrade or deactivate on another site.'=>'تم الوصول إلى حد تفعيل الترخيص. يرجى الاتصال بالدعم لترقية أو إلغاء التفعيل على موقع آخر.','This license cannot be activated. Please contact support for help.'=>'لا يمكن تفعيل هذه الرخصة. يرجى الاتصال بالدعم للحصول على المساعدة.','License server error. Please try again later or contact support for help.'=>'خطأ في خادم الرخصة. يرجى المحاولة مرة أخرى لاحقاً أو الاتصال بالدعم للحصول على المساعدة.','The license server returned an invalid response. Please try again later or contact support for help.'=>'عاد خادم الترخيص برد غير صالح. يرجى المحاولة لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','This license is inactive for this site. Please contact support for help.'=>'هذه الرخصة غير نشطة لهذا الموقع. يرجى الاتصال بالدعم للحصول على المساعدة.','Plugin activation failed. Please try again later or contact support for help.'=>'فشل تفعيل الإضافة. يرجى المحاولة لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','This action is not possible because the plugin is already installed.'=>'لا يمكن تنفيذ هذا الإجراء لأن الملحق مثبت بالفعل.','Plugin deactivation failed. Please try again later or contact support for help.'=>'فشل إلغاء تفعيل الإضافة. يرجى المحاولة لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','Plugin family not found. Please contact support for help.'=>'لم يتم العثور على عائلة الملحق. يرجى الاتصال بالدعم للحصول على المساعدة.','This action is not possible because both free and pro versions are installed. Please uninstall one version to continue.'=>'هذه العملية غير ممكنة لأن كل من النسخ المجانية والمحترفة مثبتة. يرجى إلغاء تثبيت نسخة واحدة للمتابعة.','Plugin installation failed. Please contact support for help.'=>'فشل تثبيت الملحق. يرجى الاتصال بالدعم للحصول على المساعدة.','This action is not possible because the plugin is not activated. Please activate the plugin and try again.'=>'هذه العملية غير ممكنة لأن الإضافة غير مفعلّة. يرجى تفعيل الإضافة والمحاولة مرة أخرى.','Plugin not found in our available plugins list. Please contact support for help.'=>'الإضافة غير موجودة في قائمة الإضافات المتاحة لدينا. يرجى الاتصال بالدعم للحصول على المساعدة.','This action is not possible because the plugin is not installed. Please install the plugin and try again.'=>'هذه العملية غير ممكنة لأن الإضافة غير مثبتة. يرجى تثبيت الإضافة والمحاولة مرة أخرى.','Unknown license server error. Please try again later or contact support for help.'=>'خطأ غير معروف في خادم الترخيص. يرجى المحاولة لاحقًا أو الاتصال بالدعم للحصول على المساعدة.','Define tasks that authors must complete before publishing.'=>'حدد المهام التي يجب على المؤلفين إكمالها قبل النشر.','Control who can edit and view your content.'=>'تحكم في من يمكنه تحرير وعرض المحتوى الخاص بك.','Create, manage and display authors for your content.'=>'إنشاء وإدارة وعرض المؤلفين لمحتواك.','All the tools you need to improve the block editor.'=>'جميع الأدوات التي تحتاجها لتحسين محرر الكتل.','Control your admin area and user roles.'=>'تحكم في منطقة الإدارة والأدوار الخاصة بالمستخدمين.','Schedule changes to your posts.'=>'جدولة التغييرات على منشوراتك.','Organize, schedule, and plan your publishing.'=>'تنظيم وجدولة وتخطيط النشر الخاص بك.','Approve and schedule new versions to your published posts.'=>'الموافقة على الجدولة والإصدارات الجديدة لمنشوراتك المنشورة.','Organize your posts into issues or series.'=>'تنظيم منشوراتك في قضايا أو سلاسل.','Create custom URLs for your posts and external links.'=>'إنشاء روابط مخصصة لمشاركاتك والروابط الخارجية.','Create custom statuses and publishing workflows.'=>'إنشاء حالات مخصصة وتدفقات عمل للنشر.','Dependency "%s" not found in container.'=>'المعتمد "%s" غير موجود في الحاوية.','Error validating license: %s'=>'خطأ في التحقق من الترخيص: %s','Error getting license info: %s'=>'خطأ في الحصول على معلومات الترخيص: %s','Too many requests. Please try again later.'=>'عدد كبير جدًا من الطلبات. يرجى المحاولة مرة أخرى لاحقًا.','An error occurred while processing your request.'=>'حدث خطأ أثناء معالجة طلبك.','Template not found: %s'=>'القالب غير موجود: %s','Path cannot be empty'=>'لا يمكن أن يكون المسار فارغًا','File extension cannot be empty'=>'لا يمكن أن يكون امتداد الملف فارغًا','Invalid file path: null byte detected'=>'مسار الملف غير صالح: تم اكتشاف بايت فارغ','Invalid file path: directory traversal detected'=>'مسار الملف غير صالح: تم اكتشاف تجاوز الدليل','Invalid file path: parent directory does not exist: %s'=>'مسار الملف غير صالح: الدليل الأب غير موجود: %s','Invalid file path: unable to resolve path'=>'مسار الملف غير صالح: غير قادر على حل المسار','Invalid file path: operation not allowed outside permitted directories'=>'مسار الملف غير صالح: العملية غير مسموح بها خارج الأدلة المسموح بها','Invalid download URL provided'=>'رابط التنزيل غير صالح','Download URL must use HTTP or HTTPS protocol'=>'يجب أن يستخدم رابط التنزيل بروتوكول HTTP أو HTTPS','Download URL is not from an allowed domain: %s'=>'رابط التنزيل ليس من نطاق مسموح به: %s','Download URL failed WordPress validation'=>'فشل رابط التنزيل في التحقق من صحة ووردبريس','Failed to download plugin: %s'=>'فشل في تنزيل الإضافة: %s','Downloaded plugin file does not exist'=>'ملف الإضافة الذي تم تنزيله غير موجود','Downloaded plugin file is empty'=>'ملف الإضافة الذي تم تنزيله فارغ','Cannot read downloaded plugin file'=>'لا يمكن قراءة ملف الإضافة الذي تم تنزيله','Downloaded file is not a valid ZIP archive. The download URL may be returning an error page.'=>'الملف الذي تم تنزيله ليس أرشيف ZIP صالح. قد يكون عنوان URL للتنزيل يعيد صفحة خطأ.','Failed to unzip plugin file: %s'=>'فشل في فك ضغط ملف الإضافة: %s','Failed to unzip plugin file'=>'فشل في فك ضغط ملف الإضافة','Failed to activate plugin: %s'=>'فشل في تفعيل الإضافة: %s','Failed to delete plugin: %s'=>'فشل في حذف الإضافة: %s','No update available for this plugin'=>'لا توجد تحديثات متاحة لهذه الإضافة','Invalid update information for this plugin'=>'معلومات التحديث غير صالحة لهذه الإضافة','Failed to update plugin: %s'=>'فشل في تحديث الإضافة: %s','Plugin update failed'=>'فشل تحديث الإضافة','Failed to get plugin information: %s'=>'فشل في الحصول على معلومات الإضافة: %s','.'=>'.']];